#Requires -RunAsAdministrator
[CmdletBinding()]
param(
    [Parameter(Mandatory)][string]$InstallerPath,
    [Parameter(Mandatory)][guid]$ExpectedOrganizationId,
    [Parameter(Mandatory)][guid]$ExpectedSiteId,
    # Optional: the organization/site-specific Breeze installer generated by Breeze.
    [string]$BreezeInstallerPath,
    [ValidatePattern('^[A-Fa-f0-9]{64}$')][string]$BreezeInstallerSha256,
    [ValidateRange(30,900)][int]$EnrollmentWaitSeconds = 660
)
$ErrorActionPreference = 'Stop'
if (-not [Environment]::Is64BitOperatingSystem) { throw 'This package requires Windows x64.' }
function Assert-Package([string]$Path,[string]$Hash) {
    if (-not [IO.Path]::IsPathRooted($Path) -or $Path -match '["\r\n]' -or [IO.Path]::GetExtension($Path) -ine '.msi') { throw 'Use an absolute MSI path without quotes or line breaks.' }
    if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { throw 'Installer not found.' }
    if ((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash -ine $Hash) { throw 'Installer SHA-256 does not match the approved package.' }
}
function Install-Package([string]$Path,[string]$Properties='') {
    $process=Start-Process msiexec.exe -ArgumentList ('/i "'+$Path+'" /qn /norestart '+$Properties) -WindowStyle Hidden -Wait -PassThru
    if ($process.ExitCode -notin @(0,3010)) { throw "MSI installation failed with exit code $($process.ExitCode)." }
    if ($process.ExitCode -eq 3010) { Write-Warning 'Windows reports that a restart is required.' }
}
Assert-Package $InstallerPath '727E175A37585CBB98232C188F46D221EAD9B0B05B69EFB6D2012969ECFB9E85'
if ($BreezeInstallerPath) {
    if (-not $BreezeInstallerSha256) { throw 'Supply the verified SHA-256 of the organization-specific Breeze MSI.' }
    Assert-Package $BreezeInstallerPath $BreezeInstallerSha256
}
$agent=Get-Service BreezeAgent -ErrorAction SilentlyContinue
if (-not $agent) {
    if (-not $BreezeInstallerPath) { throw 'Install the organization/site-specific Breeze agent first, or supply its MSI and SHA-256.' }
    Install-Package $BreezeInstallerPath
    $agent=Get-Service BreezeAgent -ErrorAction SilentlyContinue
    if (-not $agent) { throw 'Breeze agent service was not created. RustDesk has not been installed.' }
}
if ($agent.Status -ne 'Running') { Start-Service BreezeAgent }
$configPath=Join-Path $env:ProgramData 'Breeze\agent.yaml'
$ready=$false
$configDeadline=[DateTime]::UtcNow.AddSeconds(120)
do {
    if (Test-Path -LiteralPath $configPath -PathType Leaf) {
        $config=Get-Content -LiteralPath $configPath -Raw
        $org=[regex]::Match($config,'(?m)^org_id:\s*["'']?([a-fA-F0-9-]{36})').Groups[1].Value
        $site=[regex]::Match($config,'(?m)^site_id:\s*["'']?([a-fA-F0-9-]{36})').Groups[1].Value
        if ($org -and $org -ine $ExpectedOrganizationId.ToString()) { throw 'This device belongs to a different Breeze organization. No reassignment was attempted.' }
        if ($site -and $site -ine $ExpectedSiteId.ToString()) { throw 'This device belongs to a different Breeze site. No reassignment was attempted.' }
        $ready=($org -ieq $ExpectedOrganizationId.ToString() -and $site -ieq $ExpectedSiteId.ToString())
    }
    if (-not $ready) { Start-Sleep -Seconds 5 }
} while (-not $ready -and [DateTime]::UtcNow -lt $configDeadline)
if (-not $ready) { throw 'Breeze has not confirmed the expected organization/site in its configuration. RustDesk has not been installed.' }
# Never replace or adopt an unrelated RustDesk installation automatically.
if (Get-Service RustDesk -ErrorAction SilentlyContinue) { throw 'RustDesk is already installed. Verify its enrollment or use the managed upgrade workflow; this script is for new installations.' }
Install-Package $InstallerPath 'INSTALLPRINTER=1 CREATEDESKTOPSHORTCUTS=N CREATESTARTMENUSHORTCUTS=N CREATESTARTUPSHORTCUTS=N LAUNCH_TRAY_APP=N'
$expected=Join-Path $env:ProgramFiles 'RustDesk\RustDesk.exe'
$service=Get-CimInstance Win32_Service -Filter "Name='RustDesk'"
if (-not $service -or $service.State -ne 'Running' -or $service.PathName -notlike ('*'+$expected+'*')) { throw 'RustDesk service is not running at the expected installation path.' }
# The existing Breeze agent binds the native target to its authenticated device/org.
# Do not copy another computer's protected enrollment or put shared passwords here.
$enrollment=Join-Path $env:ProgramData 'Breeze\data\rustdesk\native-admission.dpapi'
$deadline=[DateTime]::UtcNow.AddSeconds($EnrollmentWaitSeconds)
while (-not (Test-Path -LiteralPath $enrollment -PathType Leaf) -and [DateTime]::UtcNow -lt $deadline) { Start-Sleep -Seconds 5 }
if (-not (Test-Path -LiteralPath $enrollment -PathType Leaf)) { throw 'Installed, but native enrollment is pending. Verify the Breeze device is online and in the intended organization; do not reinstall or copy enrollment files.' }
Write-Output 'Managed RustDesk installed; local enrollment exists. Verify the device organization and an unattended connection in Breeze before wider rollout.'
